{
  "name": "KanCare Medicare Buy-In Programs",
  "eligibility": {
    "age": 65,
    "income_limits": {
      "programs": [
        {
          "name": "QMB (Qualified Medicare Beneficiary)",
          "single_monthly_income": "Up to $1,350",
          "couple_monthly_income": "Up to $1,824"
        },
        {
          "name": "SLMB / LMB (Specified Low-Income Medicare Beneficiary)",
          "single_monthly_income": "$1,351 to $1,616",
          "couple_monthly_income": "$1,825 to $2,184"
        },
        {
          "name": "QI / ELMB (Qualifying Individual)",
          "single_monthly_income": "$1,617 to $1,816",
          "couple_monthly_income": "$2,185 to $2,455"
        }
      ],
      "notes": "Kansas Medicare Savings Program limits are reported in current 2026 summaries as above; older official Kansas policy pages confirm the buy-in categories and that Medicare Part B enrollment is a condition of eligibility, but the exact dollar table was not available in the official snippet returned."
    },
    "asset_limits": {
      "qmb_slmb": {
        "single": "$9,660",
        "couple": "$14,470"
      },
      "qi": {
        "single": "$9,950",
        "couple": "$14,910"
      },
      "what_counts": [
        "Countable bank accounts",
        "Stocks and bonds",
        "Non-retirement cash assets",
        "Other non-exempt resources"
      ],
      "what_is_exempt": [
        "Home you live in",
        "One vehicle",
        "Personal belongings",
        "Household goods",
        "Burial space and certain burial funds",
        "Most retirement accounts may be treated differently depending on status and rules"
      ],
      "notes": "Kansas applies federal Medicare Savings Program resource rules. Asset limits vary slightly by program tier, and QI generally has the highest allowable limit among the three listed groups."
    },
    "other_requirements": [
      "Must be entitled to Medicare Part A or enrolled in Medicare Part B, depending on category",
      "Must be a Kansas resident",
      "Must meet citizenship/qualified immigrant requirements for Kansas Medicaid-related programs",
      "QI is first-come, first-served and subject to available federal funding",
      "Part B enrollment is required or arranged through the buy-in process for eligible Medicaid beneficiaries"
    ]
  },
  "benefits": {
    "type": "financial",
    "value": {
      "QMB": "Pays Medicare Part A premium if owed, Medicare Part B premium, and Medicare deductibles, coinsurance, and copayments for Medicare-covered services.",
      "SLMB/LMB": "Pays Medicare Part B premium only.",
      "QI/ELMB": "Pays Medicare Part B premium only."
    },
    "varies_by": "priority_tier"
  },
  "application": {
    "methods": [
      "Online: https://applyforKanCare.ks.gov",
      "Phone: KanCare Clearinghouse at 800-792-4884",
      "Mail: KanCare Clearinghouse, P.O. Box 3599, Topeka, KS 66601-3599",
      "Paper application delivered through Kansas DCF offices"
    ],
    "processing_time": "Not stated in the returned official snippets; families should expect a Medicaid-style eligibility review rather than an instant approval. QI determinations can be affected by funding availability.",
    "waitlist": "QI is first-come, first-served and may effectively close or exhaust funds if the yearly federal allocation runs out; QMB and SLMB do not have a waitlist in the same way.",
    "forms": [
      "KanCare application / Medicaid application used for Medicare Savings Programs",
      "KEESM 2911 Medicare and Medicare Buy-In policy references a completed form and supporting documentation sent to the servicing Social Security office in some buy-in situations"
    ],
    "documents": [
      "Proof of Medicare Part A and/or Part B",
      "Social Security numbers",
      "Proof of Kansas residency",
      "Proof of income such as Social Security award letters, pension statements, paycheck stubs, or bank deposit records",
      "Proof of resources/assets such as bank statements if requested",
      "Identification for household members",
      "If applicable, immigration/citizenship documents",
      "Any current Medicaid or Medicare notices"
    ]
  },
  "geography": {
    "statewide": true,
    "restrictions": "Kansas statewide; administered through KanCare/Kansas Medicaid rules, not county-restricted.",
    "regional_variations": "The program itself is statewide and does not appear to vary by county. Practical experience can differ by local DCF office workload, caseworker availability, and whether a family applies online, by mail, or in person.",
    "offices_or_providers": [
      "KanCare Clearinghouse",
      "Kansas Department for Children and Families local offices",
      "Kansas Department for Aging and Disability Services information line for Medicare-buy-in questions"
    ]
  },
  "official_source": "https://khap.kdhe.ks.gov/KEESM/Oct_2023_Output/keesm2911.htm",
  "gotchas": [
    "There are three different Kansas Medicare Savings Program levels, and families often confuse them: QMB is the most generous; SLMB/LMB and QI/ELMB only pay Part B premiums.",
    "QI is not guaranteed if funds run out because it is first-come, first-served.",
    "People often miss that QMB prohibits providers from billing the beneficiary for Medicare-covered cost-sharing.",
    "A person can still qualify even if they already have Medicare; the program helps pay premiums and cost-sharing rather than replacing Medicare.",
    "The income and asset tests are separate; being under the income limit alone is not enough if resources are too high.",
    "Kansas uses the buy-in process so Medicaid beneficiaries who are entitled to Medicare Part B are enrolled in Part B as a condition of eligibility."
  ],
  "data_shape_notes": "This program is really a set of three income-tiered Medicare Savings Programs rather than one single benefit. Eligibility depends on both income and resources, the benefit changes by tier, and QI has funding-based availability."
}
